For $\lambda>0$ define $N_\lambda(X)$ as the number of triples $(a,b,c)\in \mathbb{N}^3$ with $a+b=c$, $\gcd(a,b,c)=1$ and
$\mathrm{rad}(abc) < c^{\lambda}$.

\label{lem:deBruijnRadical}
  For any $\varepsilon>0$, we have
  \begin{equation}\label{eq:bruijn}
    \#\left\{n\leqslant x : \mathrm{rad}(n)\leqslant x^\lambda\right\} \ll_\varepsilon x^{\lambda+\varepsilon}.
  \end{equation}



It suffices to show that for any integer $k\geqslant 2$ we have
\begin{align}\label{eq1}
|\{n\leqslant X:\,\, \mathrm{rad}(n)=k\}|\ll X^{O(1/\log \log X)}.
\end{align}
To prove \eqref{eq1}, write $k=p_1\cdots p_r$ as distinct primes $p_1<\cdots <p_r$. Then $\mathrm{rad}(n)=k$ implies that $n=p_1^{m_1}\cdots p_{r}^{m_r}$ for some integers $m_1,\ldots, m_r\geqslant 1$. Therefore, the number of $n\leqslant X$ in question is
\begin{align*}
|\{n\leqslant X:\,\, \mathrm{rad}(n)=k\}| &\leqslant \sum_{m_1,\ldots, m_r\geqslant 1}\mathbf{1}_{\sum_{j\leqslant r}m_j(\log p_j)\leqslant \log X}\\
&\leqslant \sum_{m_1,\ldots, m_r\geqslant 1}\int_{\mathbb{R}^r}\mathbf{1}_{\sum_{j\leqslant r}t_j(\log p_j)\leqslant \log X}\mathbf{1}_{t_j\in (m_j-1,m_j]\, \forall j\leqslant r} \textnormal{d} t_1\cdots \textnormal{d} t_r\\
&=\textnormal{vol}\Big(\big\{(t_1,\ldots, t_r)\in \mathbb{R}_{\geqslant 0}^r:\,\, t_1(\log p_1)+\cdots +t_r(\log p_r)\leqslant \log X\big\}\Big)\\
&=(\log X)^re^{O(r)}r^{-r}\prod_{j=1}^r \frac{1}{\log p_j}
\end{align*}
by calculating the volume of a simplex. Moreover, we have
\begin{align*}
\prod_{j=1}^r \log p_j\geqslant \prod_{j=2}^{r+1}\log j=\exp\left(\sum_{j=2}^{r+1}\log \log j\right)\gg (\log r)^{r}e^{-O(r)}.
\end{align*}
Hence for some $C_0>1$
\begin{align*}
|\{n\leqslant X:\,\, \mathrm{rad}(n)=k\}| \ll \left(\frac{C_0\log X}{r\log r}\right)^r\ll
\exp\Big(O\Big(\frac{\log X}{\log\log X}\Big)\Big),
\end{align*}
since $r=\omega(k)\leqslant (1+o(1))(\log X)/(\log \log X)$ by the prime number theorem.

