\label{lem:DiophantineFactor}


Let $\varepsilon\in (0,1/2)$, and let $2\leqslant n\leqslant X$ be an integer. Then there exists a factorisation
\begin{align*}
n=c\prod_{j\leqslant \frac{5}{2}\varepsilon^{-2}}x_j^{j},
\end{align*}
for positive integers $x_j,c$ such that $c\leqslant X^{\varepsilon/2}$, the $x_j$ are pairwise coprime, and \begin{align*}
X^{-\varepsilon}\prod_{j\leqslant \frac{5}{2}\varepsilon^{-2}}x_j \leqslant \mathrm{rad}(n) \leqslant X^{\varepsilon}\prod_{j\leqslant \frac{5}{2}\varepsilon^{-2}}x_j.
\end{align*}



  Fix $2\leqslant n\leqslant X$ and let $K=2\lceil \varepsilon^{-1}\rceil$, $M=\lfloor \frac{5}{2}\varepsilon^{-2}\rfloor$. Define
\begin{align*}
y_j:=\prod_{p^j\|n} p.
\end{align*}
For $j\leqslant M$, we set
\begin{alignat*}{2}
x_j:=\begin{cases}y_j & \text{for $j\neq K$},\\
y_j\prod_{m>M}y_m^{\lfloor m/K\rfloor} & \text{for $j=K$},
\end{cases}\qquad\text{and}\qquad
c\,:=\prod_{m>M}y_m^{m-K\lfloor m/K\rfloor}.
\end{alignat*}
All the $x_j$ are pairwise coprime, since the $y_j$ are pairwise coprime.


Note that by definition $c\prod_{j\leqslant M}x_j^j=\prod_{m\geqslant 1}y_m^m=n\leqslant X$. In particular,
\begin{align*}
\prod_{m\geqslant M}y_m\leqslant \Big(\prod_{m\geqslant M}y_m^{m}\Big)^{1/M}\leqslant X^{1/M}.
\end{align*}
Then, since $m-K\lfloor m/K\rfloor \leqslant K$, it follows from the definition of $c$ that
\begin{align*}
c\leqslant \prod_{m\geqslant M}y_m^K\leqslant X^{K/M}\leqslant X^{\varepsilon/2}.
\end{align*}
Thus
\[
\mathrm{rad}(n)\leqslant \mathrm{rad}(c)\prod_{j\leqslant M}\mathrm{rad}(x_j)\leqslant X^{\varepsilon/2} \prod_{j\leqslant M} x_j.
\]

On the other hand, we have
\begin{align*}
x_K = y_K\prod_{m> M}y_m^{\lfloor m/K\rfloor}\leqslant \Big(y_K^K\cdot\prod_{m> M}y_m^m\Big)^{1/K}\leqslant n^{1/K}\leqslant X^{\varepsilon/2}.
\end{align*}
Recalling that the $y_j$ are squarefree and pairwise coprime for $j\neq K$, gives the lower bound
\[
\mathrm{rad}(n)=\prod_{m\geqslant 1}y_m \geqslant \prod_{\substack{j\leqslant M\\j\neq K}}x_j\geqslant X^{-\varepsilon/2}\prod_{j\leqslant M}x_j,
\]
as claimed.

\begin{alignat*}{2}
x_j:=\begin{cases}y_j & \text{for $j\neq K$},\\
y_j\prod_{m>M}y_m^{\lfloor m/K\rfloor} & \text{for $j=K$},
\end{cases}\qquad\text{and}\qquad
c\,:=\prod_{m>M}y_m^{m-K\lfloor m/K\rfloor}.
\end{alignat*}

