X^{\beta-\varepsilon}\ll_{\varepsilon}\prod_{j=1}^{d}Y_j\leqslant 2 X^{\beta+\varepsilon},\quad
X^{\gamma-\varepsilon}\ll_{\varepsilon}\prod_{j=1}^{d}Z_j\leqslant 2 X^{\gamma+\varepsilon}
\end{align}
and
\begin{align}\label{eq:xiyizi_2}
\prod_{j=1}^d X_j^j \leqslant X, \quad \prod_{j=1}^d Y_j^j\leqslant X,\quad X^{1-\varepsilon^2}\ll_{\varepsilon} \prod_{j=1}^d Z_j^j\leqslant X
\end{align}
and pairwise coprime integers $1\leqslant c_1,c_2,c_3\leqslant X^{\varepsilon}$, such that
\begin{align*}
S^*_{\alpha,\beta,\gamma}(X) \ll_{\varepsilon} X^{\varepsilon}B_d(\mathbf{c},\mathbf{X},\mathbf{Y},\mathbf{Z}).
\end{align*}

\begin{align}\label{eq:xiyizi_2}
