\label{prop:FourierAnalysis}

  Let $d\geqslant 1$, $\varepsilon>0$ and $A\geqslant 1$ be fixed.
  Let \[
  X_1,\ldots, X_d, Y_1,\ldots, Y_d,Z_1,\ldots, Z_d\geqslant 1
  \]
  and put
  \begin{equation}\label{eq:Delta}
  \Delta =\max_{1\leqslant i\leqslant d}(X_i Y_i Z_i).
  \end{equation}
  Let $\mathbf{c}=(c_1,c_2,c_3)\in \mathbb{Z}^3$ satisfy $0<|c_1|,|c_2|,|c_3|\leqslant \Delta^A$.
  Then
  \begin{align*}
  B_d(\mathbf{c},\mathbf{X},\mathbf{Y},\mathbf{Z}) \ll
  \Delta^\varepsilon \frac{\prod_{j\leqslant d} \big(X_j Y_j Z_j(Y_j+Z_j)\big)^{\frac{1}{2}}}{\max_{i>1}\prod_{j\equiv 0\bmod i}Z_j^{\frac{1}{2}}}.
  \end{align*}


By the orthogonality of characters, we have
\begin{align*}
B_d(\mathbf{c},\mathbf{X},\mathbf{Y},\mathbf{Z}) &\leqslant \int_0^1 \sum_{x_j\sim X_j}\sum_{y_j\sim Y_i}\sum_{z_j\sim Z_j}e\Big(\alpha\Big(c_1\prod_{j\leqslant d}x_j^j+c_2\prod_{j\leqslant d}y_j^j-c_3\prod_{j\leqslant d}z_j^j\Big)\Big)\mathrm{d}{\alpha} \nonumber\\
&= \int_{0}^1 S_1(\alpha)S_2(\alpha)S_3(-\alpha)\, \mathrm{d} \alpha,
\end{align*}
where
\begin{align*}
&S_1(\alpha)=\sum_{x_1\sim X_1,\ldots, x_d\sim X_d}e(\alpha c_1x_1x_2^2\cdots x_d^d),\quad S_2(\alpha)=\sum_{y_1\sim Y_1,\ldots, y_d\sim Y_d}e(\alpha c_2y_1y_2^2\cdots y_d^d),\\
&S_3(\alpha)=\sum_{z_1\sim Z_1,\ldots, z_d\sim Z_d}e(\alpha c_3z_1z_2^2\cdots z_d^d).
\end{align*}
Then Cauchy-Schwarz gives
\begin{align}\label{eq:Bc123}
B_d(\mathbf{c},\mathbf{X},\mathbf{Y},\mathbf{Z}) \leqslant \left(\int_{0}^1|S_1(\alpha)|^2\, \textnormal{d}\alpha\right)^{\frac{1}{2}}\left(\int_{0}^1|S_2(\alpha)|^2|S_3(\alpha)|^2\, \textnormal{d}\alpha\right)^{\frac{1}{2}} \ =: \sqrt{I_1\,I_2}.
\end{align}
By Parseval's identity and the divisor bound, we have
\begin{align}\label{eq:prop3.1I1}\begin{split}
I_1 =\int_{0}^1|S_1(\alpha)|^2\, \textnormal{d}\alpha
&= \sum_{x_j\sim X_j\forall j}\#\big\{(x_1',\ldots, x_d')\colon x_j'\sim X_j\,\, \forall j,\, x_1x_2^2\cdots x_d^d=x_1'x_2'^2\cdots x_d'^d \big\}\\
& \ll \prod_{j\leqslant d} X_j^{1+\varepsilon},
\end{split}
\end{align}
for any $\varepsilon>0$.
Using Cauchy-Schwarz again, for any $i\leqslant d$ we have
\begin{align*}
|S_3(\alpha)|^2 = \bigg|\sum_{z_j\sim Z_j\,\forall j\leqslant d}e(\alpha c_3z_1\cdots z_d^d)\bigg|^2
&\leqslant T(\alpha)\prod_{j\not \equiv 0\bmod i}Z_{j},
\end{align*}
where
\[
T(\alpha)=
